    "valor": 490000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_12e7f172f0",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
